-- REVIEW ONLY. One CREATE OR REPLACE statement. Execute as SQL script in DBeaver.
USE auxiliares;
DELIMITER $$
CREATE OR REPLACE TRIGGER `TRG_FB_CONSULTAS_HIST_UPDATE` AFTER UPDATE ON `FB_CIU_CONSULTAS_WEB` FOR EACH ROW
BEGIN
IF NEW.VERSION>OLD.VERSION THEN INSERT INTO FB_CONSULTAS_HISTORIAL (ID_CONSULTA,VERSION,TIPO_OPERACION,USUARIO_MODIFICADOR_ID,DATOS_ANTERIORES,DATOS_NUEVOS) VALUES (NEW.ID_CONSULTA,NEW.VERSION,'MODIFICACION',NEW.USUARIO_MODIFICADOR_ID,JSON_OBJECT('id_consulta',CAST(OLD.`ID_CONSULTA` AS CHAR),'padron',OLD.`PADRON`,'padcod',CAST(OLD.`PADCOD` AS CHAR),'localidad_padron',OLD.`LOCALIDAD_PADRON`,'nombre_completo',OLD.`NOMBRE_COMPLETO`,'rel_cod',OLD.`REL_COD`,'tipo_documento',OLD.`TIPO_DOCUMENTO`,'documento',OLD.`DOCUMENTO`,'domicilio_calle',OLD.`DOMICILIO_CALLE`,'domicilio_puerta',OLD.`DOMICILIO_PUERTA`,'domicilio_block',OLD.`DOMICILIO_BLOCK`,'domicilio_apto',OLD.`DOMICILIO_APTO`,'domicilio_localidad',OLD.`DOMICILIO_LOCALIDAD`,'domicilio_departamento',OLD.`DOMICILIO_DEPARTAMENTO`,'telefono_1',OLD.`TELEFONO_1`,'tipo_telefono_1',OLD.`TIPO_TELEFONO_1`,'telefono_2',OLD.`TELEFONO_2`,'tipo_telefono_2',OLD.`TIPO_TELEFONO_2`,'telefono_3',OLD.`TELEFONO_3`,'tipo_telefono_3',OLD.`TIPO_TELEFONO_3`,'telefono_4',OLD.`TELEFONO_4`,'tipo_telefono_4',OLD.`TIPO_TELEFONO_4`,'telefono_5',OLD.`TELEFONO_5`,'tipo_telefono_5',OLD.`TIPO_TELEFONO_5`,'mail_1',OLD.`MAIL_1`,'mail_2',OLD.`MAIL_2`,'mail_3',OLD.`MAIL_3`,'mail_4',OLD.`MAIL_4`,'mail_5',OLD.`MAIL_5`,'tipo_consulta',OLD.`TIPO_CONSULTA`,'descripcion',OLD.`DESCRIPCION`,'usuario_creador_id',OLD.`USUARIO_CREADOR_ID`,'fecha_alta',OLD.`FECHA_ALTA`,'fecha_modificacion',OLD.`FECHA_MODIFICACION`,'version',OLD.`VERSION`,'usuario_modificador_id',OLD.`USUARIO_MODIFICADOR_ID`,'id_persona',CAST(OLD.`ID_PERSONA` AS CHAR),'id_persona_cp',CAST(OLD.`ID_PERSONA_CP` AS CHAR),'concod',CAST(OLD.`CONCOD` AS CHAR),'relacion_declarada',OLD.`RELACION_DECLARADA`,'domicilio_declarado_json',JSON_QUERY(OLD.`DOMICILIO_DECLARADO_JSON`,'$'),'referencias_cp_json',JSON_QUERY(OLD.`REFERENCIAS_CP_JSON`,'$'),'actualiza_contacto',OLD.`ACTUALIZA_CONTACTO`,'contacto_version_esperada',OLD.`CONTACTO_VERSION_ESPERADA`),JSON_OBJECT('id_consulta',CAST(NEW.`ID_CONSULTA` AS CHAR),'padron',NEW.`PADRON`,'padcod',CAST(NEW.`PADCOD` AS CHAR),'localidad_padron',NEW.`LOCALIDAD_PADRON`,'nombre_completo',NEW.`NOMBRE_COMPLETO`,'rel_cod',NEW.`REL_COD`,'tipo_documento',NEW.`TIPO_DOCUMENTO`,'documento',NEW.`DOCUMENTO`,'domicilio_calle',NEW.`DOMICILIO_CALLE`,'domicilio_puerta',NEW.`DOMICILIO_PUERTA`,'domicilio_block',NEW.`DOMICILIO_BLOCK`,'domicilio_apto',NEW.`DOMICILIO_APTO`,'domicilio_localidad',NEW.`DOMICILIO_LOCALIDAD`,'domicilio_departamento',NEW.`DOMICILIO_DEPARTAMENTO`,'telefono_1',NEW.`TELEFONO_1`,'tipo_telefono_1',NEW.`TIPO_TELEFONO_1`,'telefono_2',NEW.`TELEFONO_2`,'tipo_telefono_2',NEW.`TIPO_TELEFONO_2`,'telefono_3',NEW.`TELEFONO_3`,'tipo_telefono_3',NEW.`TIPO_TELEFONO_3`,'telefono_4',NEW.`TELEFONO_4`,'tipo_telefono_4',NEW.`TIPO_TELEFONO_4`,'telefono_5',NEW.`TELEFONO_5`,'tipo_telefono_5',NEW.`TIPO_TELEFONO_5`,'mail_1',NEW.`MAIL_1`,'mail_2',NEW.`MAIL_2`,'mail_3',NEW.`MAIL_3`,'mail_4',NEW.`MAIL_4`,'mail_5',NEW.`MAIL_5`,'tipo_consulta',NEW.`TIPO_CONSULTA`,'descripcion',NEW.`DESCRIPCION`,'usuario_creador_id',NEW.`USUARIO_CREADOR_ID`,'fecha_alta',NEW.`FECHA_ALTA`,'fecha_modificacion',NEW.`FECHA_MODIFICACION`,'version',NEW.`VERSION`,'usuario_modificador_id',NEW.`USUARIO_MODIFICADOR_ID`,'id_persona',CAST(NEW.`ID_PERSONA` AS CHAR),'id_persona_cp',CAST(NEW.`ID_PERSONA_CP` AS CHAR),'concod',CAST(NEW.`CONCOD` AS CHAR),'relacion_declarada',NEW.`RELACION_DECLARADA`,'domicilio_declarado_json',JSON_QUERY(NEW.`DOMICILIO_DECLARADO_JSON`,'$'),'referencias_cp_json',JSON_QUERY(NEW.`REFERENCIAS_CP_JSON`,'$'),'actualiza_contacto',NEW.`ACTUALIZA_CONTACTO`,'contacto_version_esperada',NEW.`CONTACTO_VERSION_ESPERADA`)); END IF;
END$$
DELIMITER ;
